import React, {Component} from 'react';
import factory from "../ethereum/factory";
import Tender from "../ethereum/tender";
import { Card, Button, Menu } from "semantic-ui-react";
import { Link } from "../routes";
import Layout from "../components/Layout";

const FulfilledTenders = ({ tenders }) => {
  /*Creates a array containing all relevant attributes of tender cards
    to be displayed
*/
  const renderTenders = () => {
      const items = tenders.map(async (address) => {
          const tender = Tender(address);
        
        const status = await tender.methods.getTenderState().call();
        var isComplete;
        if (status === "Ongoing") isComplete = false;
          else isComplete = true;
        console.log(isComplete)
          ;
        if (isComplete) {
            return {
              header: address,
              description: (
                <Link route={`/tenders/${address}`}>
                  <a>View Tender</a>
                </Link>
              ),
              fluid: true,
            };
          }
    });
    return <Card.Group items={items} />;
  };

  return (
    //Layout is a custom tag created in components/layout
    <Layout>
      <div>
        {renderTenders()}
      </div>
    </Layout>
  );
};

export const getServerSideProps = async () => {
  const tenders = await factory.methods.getDeployedTenders().call();
  console.log(tenders);
  return { props: { tenders } };
};

export default FulfilledTenders;
